"""Frozen AI Web App entry; identity is generated by the reviewed package builder."""
import os
from pathlib import Path
import sys
import time

from ai_workbench.service import AiService
from opendesk_worker.__main__ import main as serve
from opendesk_worker.registry import MethodResult
from opendesk_worker.protocol import ProtocolError
from _build_identity import IDENTITY


def main():
    data = os.environ.get("OPENDESK_MODULE_DATA_DIR", "")
    if not data or not Path(data).is_absolute():
        raise RuntimeError("Host must provide an absolute module data directory.")
    web = Path(getattr(sys, "_MEIPASS", Path(__file__).parent)) / "web"
    service = AiService(Path(data), web, version=IDENTITY["version"])

    def configure(registry):
        def handler(fn):
            def call(params):
                if params:
                    raise ProtocolError("INVALID_PARAMS", "This control method accepts no arguments.")
                return MethodResult(fn())
            return call
        registry.register("module.identity", handler(lambda: IDENTITY))
        registry.register("module.webapp", handler(lambda: {"url": service.start()}))
        registry.register("module.prepareShutdown", handler(service.prepare_shutdown))
        registry.register("ai.status", handler(service.status))
    try:
        return serve(configure)
    finally:
        while not service.prepare_shutdown()["ready"]:
            time.sleep(0.05)
        service.close()


if __name__ == "__main__":
    raise SystemExit(main())
